CAMPUS_ORDER = ["milai-north", "milai-east", "milai-west", "milai-elgon-view"]


def first_names(slug: str, female: bool) -> list[str]:
    """The first names one campus draws its logins from. Each Milai campus gets its own share of the list, so
    no two campuses ever want the same first name and a campus's cast never depends on which was filled first."""
    pool = FEMALE_FIRST if female else MALE_FIRST
    if slug not in CAMPUS_ORDER:
        return list(pool)
    i, n = CAMPUS_ORDER.index(slug), len(CAMPUS_ORDER)
    return [name for k, name in enumerate(pool) if k % n == i]
